/**
 * The synthetic weight set and fixed position behind the nn-runtime goldens.
 *
 * This lives outside the test because `scripts/regenerate-nn-runtime-golden.mjs`
 * has to build the *identical* blob to feed the PyTorch reference. When the two
 * kept their own copies the fixture could only be regenerated by hand-editing
 * both in step, and a golden that no longer matches the blob it claims to come
 * from is worse than no golden -- the fnv1a32 check in the test exists to catch
 * exactly that, and it can only work if there is one definition to hash.
 *
 * The plane count comes from the encoder. It was written out as a literal `8`
 * here and in the runtime while the encoder moved to 10, and the disagreement
 * surfaced only as a golden mismatch.
 */

import { applyAction, createInitialState } from '../../js/normal-duel-engine.mjs';
import { NN_INPUT_PLANES } from '../../js/normal-duel-nn-encoding.mjs';

export const CONFIG_9X9 = Object.freeze({
  ruleset: 'normal-duel-v1', rows: 9, columns: 9,
  start: { A: { r: 8, c: 4 }, B: { r: 0, c: 4 } },
  goalRows: { A: 0, B: 8 }, initialStock: { A: 10, B: 10 },
  jumpRule: 'permissive-adjacent-exit-v1', repetitionThreshold: 3, plyCap: 200, firstPlayer: 'A'
});

export const ROWS = 9;
export const COLUMNS = 9;
export const CELLS = ROWS * COLUMNS;
export const POLICY_SIZE = 209;
export const FEATURE_LEN = NN_INPUT_PLANES * CELLS;

const CHANNELS = 64;
const BLOCKS = 6;
const POLICY_CHANNELS = 3;
const VALUE_CHANNELS = 32;
const VALUE_POOLS = 3;
const VALUE_HIDDEN = 64;

/** A fixed non-trivial position: a few pawn moves and a wall from each side. */
export function fixedState() {
  const actions = [
    { kind: 'pawn', to: { r: 7, c: 4 } },
    { kind: 'pawn', to: { r: 1, c: 4 } },
    { kind: 'wall', wall: 'H-3-3' },
    { kind: 'pawn', to: { r: 2, c: 4 } },
    { kind: 'pawn', to: { r: 6, c: 4 } },
    { kind: 'wall', wall: 'V-5-5' }
  ];
  return actions.reduce((state, action) => applyAction(CONFIG_9X9, state, action),
    createInitialState(CONFIG_9X9));
}

/** A synthetic-but-valid weight set, so structural tests need no artifacts. */
export function syntheticWeightSet() {
  const spec = [
    ['stem.conv.weight', [CHANNELS, NN_INPUT_PLANES, 3, 3]], ['stem.conv.bias', [CHANNELS]]
  ];
  for (let i = 0; i < BLOCKS; i += 1) {
    spec.push([`block${i}.conv1.weight`, [CHANNELS, CHANNELS, 3, 3]], [`block${i}.conv1.bias`, [CHANNELS]]);
    spec.push([`block${i}.conv2.weight`, [CHANNELS, CHANNELS, 3, 3]], [`block${i}.conv2.bias`, [CHANNELS]]);
  }
  spec.push(['policy.conv.weight', [POLICY_CHANNELS, CHANNELS, 1, 1]], ['policy.conv.bias', [POLICY_CHANNELS]]);
  spec.push(['value.conv.weight', [VALUE_CHANNELS, CHANNELS, 1, 1]], ['value.conv.bias', [VALUE_CHANNELS]]);
  spec.push(['value.fc1.weight', [VALUE_HIDDEN, VALUE_POOLS * VALUE_CHANNELS]], ['value.fc1.bias', [VALUE_HIDDEN]]);
  spec.push(['value.fc2.weight', [1, VALUE_HIDDEN]], ['value.fc2.bias', [1]]);

  const tensors = [];
  let offset = 0;
  for (const [name, shape] of spec) {
    const count = shape.reduce((product, dimension) => product * dimension, 1);
    tensors.push({ name, shape, dtype: 'float32', byteOffset: offset, byteLength: count * 4, count });
    offset += count * 4;
  }
  const buffer = new ArrayBuffer(offset);
  const floats = new Float32Array(buffer);
  // Deterministic filler: a fixed LCG, never Math.random.
  let seed = 12345;
  for (let i = 0; i < floats.length; i += 1) {
    seed = (seed * 1103515245 + 12345) >>> 0;
    floats[i] = ((seed >>> 8) / 0x1000000 - 0.5) * 0.1;
  }
  const manifest = {
    formatVersion: 1, byteOrder: 'little', layout: 'C-contiguous', flattenOrder: 'CHW',
    policySize: POLICY_SIZE,
    input: { planes: NN_INPUT_PLANES, rows: ROWS, columns: COLUMNS },
    architecture: {
      blocks: BLOCKS, channels: CHANNELS, policyHeadChannels: POLICY_CHANNELS,
      valueHeadChannels: VALUE_CHANNELS, valueHidden: VALUE_HIDDEN
    },
    blobBytes: offset,
    tensors
  };
  return { manifest, buffer };
}

/** FNV-1a over a byte range: pins the fixture to the exact blob it was made from. */
export function fnv1a32(buffer) {
  const bytes = new Uint8Array(buffer);
  let hash = 0x811c9dc5;
  for (let i = 0; i < bytes.length; i += 1) {
    hash ^= bytes[i];
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash.toString(16).padStart(8, '0');
}
